<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/bootstrap.php';
requireLogin();
$type=(string)($_GET['type']??$_POST['type']??'');$id=filter_input($_SERVER['REQUEST_METHOD']==='POST'?INPUT_POST:INPUT_GET,'id',FILTER_VALIDATE_INT);
if(!in_array($type,['lost','found'],true)||!$id){require __DIR__.'/errors/404.php';exit;}
$pdo=getDatabaseConnection();$table=$type==='lost'?'lost_items':'found_items';$idColumn=$type==='lost'?'lost_id':'found_id';$ownerColumn=$type==='lost'?'user_id':'finder_id';$dateColumn=$type==='lost'?'lost_date':'found_date';
$statement=$pdo->prepare("SELECT * FROM {$table} WHERE {$idColumn}=:id AND {$ownerColumn}=:user_id");$statement->execute(['id'=>$id,'user_id'=>currentUser()['user_id']]);$report=$statement->fetch();if(!$report){require __DIR__.'/errors/404.php';exit;}
if($report['status']!=='submitted')redirectWithFlash('my_reports.php','error','Only submitted reports can be edited or cancelled.');
$categories=$pdo->query('SELECT * FROM categories ORDER BY category_name')->fetchAll();$buildings=$pdo->query('SELECT * FROM buildings ORDER BY building_name')->fetchAll();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!validCsrfToken($_POST['csrf_token']??null))$errors[]='Your session expired.';$action=(string)($_POST['action']??'update');
    if($action==='cancel'&&!$errors){$pdo->prepare("UPDATE {$table} SET status='closed' WHERE {$idColumn}=:id AND {$ownerColumn}=:user_id AND status='submitted'")->execute(['id'=>$id,'user_id'=>currentUser()['user_id']]);redirectWithFlash('my_reports.php','success','Report cancelled successfully.');}
    $itemName=trim((string)($_POST['item_name']??''));$description=trim((string)($_POST['description']??''));$location=trim((string)($_POST['specific_location']??''));$date=(string)($_POST['incident_date']??'');$categoryId=filter_input(INPUT_POST,'category_id',FILTER_VALIDATE_INT);$buildingId=filter_input(INPUT_POST,'building_id',FILTER_VALIDATE_INT);
    if($itemName==='')$errors[]='Item name is required.';if(!$categoryId)$errors[]='Select a category.';if($description==='')$errors[]='Description is required.';$dateObject=DateTime::createFromFormat('Y-m-d',$date);if(!$dateObject||$dateObject->format('Y-m-d')!==$date||$date>date('Y-m-d'))$errors[]='Enter a valid date.';
    $newImage=uploadItemImage($_FILES['image']??[],$errors);$imagePath=$newImage?:$report['image_path'];
    if(!$errors&&$action==='update'){try{$update=$pdo->prepare("UPDATE {$table} SET item_name=:item_name,category_id=:category_id,building_id=:building_id,description=:description,specific_location=:location,{$dateColumn}=:incident_date,image_path=:image_path WHERE {$idColumn}=:id AND {$ownerColumn}=:user_id AND status='submitted'");$update->execute(['item_name'=>$itemName,'category_id'=>$categoryId,'building_id'=>$buildingId?:null,'description'=>$description,'location'=>$location?:null,'incident_date'=>$date,'image_path'=>$imagePath,'id'=>$id,'user_id'=>currentUser()['user_id']]);if($newImage&&$report['image_path'])@unlink(__DIR__.'/'.$report['image_path']);redirectWithFlash("report_details.php?type={$type}&id={$id}",'success','Report updated successfully.');}catch(Throwable $exception){if($newImage)@unlink(__DIR__.'/'.$newImage);throw $exception;}}
}
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Edit Report</title><link rel="stylesheet" href="assets/css/style.css"></head><body><header class="site-header"><a class="brand brand-with-mark" href="dashboard.php"><span class="brand-mark">LU</span>Liwa University Lost & Found</a><a href="my_reports.php">My Reports</a></header><main class="form-page"><section class="item-form-card"><p class="eyebrow">Report management</p><h1>Edit <?=e(ucfirst($type))?> Report</h1><?php if($errors):?><div class="alert alert-error"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrfToken())?>"><input type="hidden" name="type" value="<?=e($type)?>"><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><label>Item name<input name="item_name" value="<?=e($report['item_name'])?>" required></label><label>Category<select name="category_id"><?php foreach($categories as $category):?><option value="<?=(int)$category['category_id']?>" <?=(int)$report['category_id']===(int)$category['category_id']?'selected':''?>><?=e($category['category_name'])?></option><?php endforeach;?></select></label><label>Building<select name="building_id"><option value="">Not specified</option><?php foreach($buildings as $building):?><option value="<?=(int)$building['building_id']?>" <?=(int)$report['building_id']===(int)$building['building_id']?'selected':''?>><?=e($building['building_name'])?></option><?php endforeach;?></select></label><label>Specific location<input name="specific_location" value="<?=e((string)$report['specific_location'])?>"></label><label>Date<input type="date" name="incident_date" value="<?=e($report[$dateColumn])?>" max="<?=date('Y-m-d')?>" required></label><label>Replace photo<input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label></div><label>Description<textarea name="description" rows="5" required><?=e($report['description'])?></textarea></label><div class="form-actions"><button class="button button-primary" name="action" value="update">Save Changes</button><button class="button danger-button" name="action" value="cancel" formnovalidate onclick="return confirm('Cancel this report? This action cannot be undone.')">Cancel Report</button></div></form></section></main></body></html>
